#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> z(1, 1);
    long long total = 0;
    for (int i = 2; i <= n; ++i) {
        int size = ((i - 1) * i) / 2 + 1;
        vector<long long> new_z(size, 0);
        vector<long long> d(z.size() + 1, 0);
        for (int w = (int)z.size() - 1; w >= 0; --w) {
            d[w] = (d[w + 1] + z[w]) % mod;
        }
        for (int w = 0; w < size; ++w) {
            int L = max(0, w + 1 - i);
            int R = min((int)z.size() - 1, w);
            new_z[w] = d[L] - d[R + 1];
            if (new_z[w] < 0) new_z[w] += mod;
        }
        vector<long long> e(d.size() + 1, 0);
        vector<long long> f(d.size() + 1, 0);
        for (int w = 0; w < (int)d.size() - 1; ++w) {
            e[w + 1] = (e[w] + d[w]) % mod;
            f[w + 1] = (f[w] - (long long)w * d[w]) % mod;
            if (f[w + 1] < 0) f[w + 1] += mod;
        }
        int R = (int)z.size();
        long long bbb = 0;
        int start_jj = max(0, (int)z.size() - i);
        for (int jj = start_jj; jj < (int)z.size() - 1; ++jj) {
            int L = jj + 2;
            bbb += ((( (e[R] - e[L] + mod) % mod) * (i + 1 + jj) + ( (f[R] - f[L] + mod) % mod)) * z[jj]) % mod;
        }
        for (int jj = 0; jj < (int)z.size() - i; ++jj) {
            int L = jj + 2;
            int R2 = i + jj;
            long long val = ((( (e[R2 + 1] - e[L] + mod) % mod) * (i + 1 + jj) + ( (f[R2 + 1] - f[L] + mod) % mod)) * z[jj]) % mod;
            bbb += val;
        }
        total = (total + (bbb % mod) * A(n, n - i)) % mod;
        z = new_z;
    }
    cout << total % mod << "\n";
    return 0;
}
